SELECT b.id,c.id,t.id,'Past-exam question quality boundary','Fourteen questions and their printed answer grid are visually readable. Only question 9 is admitted because its complete stem, options, printed key, source label, and independently corroborated 1861–1865 premise all meet the quality gate; thirteen questions remain withheld.',681,'Past-exam question quality boundary',681,'high'::confidence_level,'dbc5cd17c8fd6a83027305baf332e7e120fc6b6c133a0802cb2a965948afa25c'
FROM public.books b JOIN public.chapters c ON c.book_id=b.id AND c.slug='europe' JOIN public.topics t ON t.chapter_id=c.id AND t.slug='history-mcq-review-681'
WHERE b.title='Jubayer''s GK' ON CONFLICT (canonical_hash) DO UPDATE SET content=EXCLUDED.content,confidence=EXCLUDED.confidence;
